## Part 5 — HostObjects

HostObjects expose full C++ classes to JavaScript — an object with methods, not just a standalone function.

```cpp
class AudioPipelineHostObject : public jsi::HostObject {
public:
    explicit AudioPipelineHostObject(/* deps */) { /* init */ }
    ~AudioPipelineHostObject() override { /* RAII cleanup */ }

    // Called when JS reads obj.propertyName
    jsi::Value get(jsi::Runtime& rt, const jsi::PropNameID& name) override {
        std::string propName = name.utf8(rt);

        if (propName == "start") {
            return jsi::Function::createFromHostFunction(rt, name, 0,
                [this](jsi::Runtime& rt, const jsi::Value&,
                       const jsi::Value*, size_t) -> jsi::Value {
                    start();
                    return jsi::Value::undefined();
                });
        }
        if (propName == "volume") {
            return jsi::Value(volume_);
        }
        return jsi::Value::undefined();
    }

    // Called when JS writes obj.propertyName = value
    void set(jsi::Runtime& rt, const jsi::PropNameID& name,
             const jsi::Value& value) override {
        if (name.utf8(rt) == "volume") {
            volume_ = value.asNumber();
        }
    }

private:
    double volume_ = 1.0;
    void start() { /* ... */ }
};
```

**Installing a HostObject:**

```cpp
void install(jsi::Runtime& rt) {
    auto obj = std::make_shared<AudioPipelineHostObject>();
    auto jsObj = jsi::Object::createFromHostObject(rt, obj);
    rt.global().setProperty(rt, "AudioPipeline", std::move(jsObj));
}
```

**From JavaScript:**
```js
AudioPipeline.start();
AudioPipeline.volume = 0.8;
```

