```kotlin
class AudioModule(reactContext: ReactApplicationContext) :
    ReactContextBaseJavaModule(reactContext) {

    companion object {
        init {
            System.loadLibrary("audio")  // loads libaudio.so
        }
    }

    // Called from JNI — entry point for install()
    external fun nativeInstall(jsiPtr: Long)

    override fun initialize() {
        super.initialize()
        val jsContext = reactApplicationContext
            .javaScriptContextHolder?.get() ?: return
        nativeInstall(jsContext)
    }
}
