**JNI bridge (cpp/jni.cpp):**
```cpp
extern "C" JNIEXPORT void JNICALL
Java_com_myapp_AudioModule_nativeInstall(JNIEnv* env, jobject thiz, jlong jsiPtr) {
    auto* runtime = reinterpret_cast<facebook::jsi::Runtime*>(jsiPtr);
    install(*runtime);
}
